@Override
    public NonNullList<PassiveSkill> getPlayerSkills() {
        return skills;
    }

@Override
    public int getSkillPoints() {
        return skillPoints;
    }

@Override
    public void setSkillPoints(int skillPoints) {
        this.skillPoints = skillPoints;
    }

@Override
    public void grantSkillPoints(int skillPoints) {
        this.skillPoints += skillPoints;
    }

@Override
    public boolean learnSkill(@Nonnull PassiveSkill passiveSkill) {
        if (skillPoints == 0) {
            return false;
        }
        if (skills.contains(passiveSkill)) {
            return false;
        }
        skillPoints--;
        return skills.add(passiveSkill);
    }

@Override
    public boolean grantSkill(PassiveSkill passiveSkill) {
        if (skills.contains(passiveSkill)) {
            return false;
        }
        return skills.add(passiveSkill);
    }

@Override
    public boolean isTreeReset() {
        return treeReset;
    }

@Override
    public void setTreeReset(boolean reset) {
        treeReset = reset;
    }

@Override
    public void resetTree(ServerPlayer player) {
        skillPoints += getPlayerSkills().size();
        getPlayerSkills().forEach(skill -> skill.remove(player));
        getPlayerSkills().clear();
    }

@Override
    public CompoundTag serializeNBT() {
        CompoundTag tag = new CompoundTag();
        tag.putUUID("TreeVersion", TREE_VERSION);
        tag.putInt("Points", skillPoints);
        tag.putBoolean("TreeReset", treeReset);
        ListTag skillsTag = new ListTag();
        skills.forEach(skill -> skillsTag.add(StringTag.valueOf(skill.getId().toString())));
        tag.put("Skills", skillsTag);
        return tag;
    }

@Override
    public void deserializeNBT(CompoundTag tag) {
        skills.clear();
        UUID treeVersion = tag.hasUUID("TreeVersion") ? tag.getUUID("TreeVersion") : null;
        skillPoints = tag.getInt("Points");
        ListTag skillsTag = tag.getList("Skills", Tag.TAG_STRING);
        if (!TREE_VERSION.equals(treeVersion)) {
            skillPoints += skillsTag.size();
            treeReset = true;
            return;
        }
        for (Tag skillTag : skillsTag) {
            ResourceLocation skillId = ResourceLocation.parse(skillTag.getAsString());
            PassiveSkill passiveSkill = SkillsReloader.getSkillById(skillId);
            if (passiveSkill == null || passiveSkill.isInvalid()) {
                skills.clear();
                treeReset = true;
                skillPoints += skillsTag.size();
                return;
            }
            skills.add(passiveSkill);
        }
    }

@SubscribeEvent
    public static void attachCapability(AttachCapabilitiesEvent<Entity> event) {
        if (!(event.getObject() instanceof Player)) {
            return;
        }
        PlayerSkillsProvider provider = new PlayerSkillsProvider();
        event.addCapability(CAPABILITY_ID, provider);
    }

@SubscribeEvent
    public static void persistThroughDeath(PlayerEvent.Clone event) {
        if (event.getEntity().level().isClientSide) {
            return;
        }
        event.getOriginal().reviveCaps();
        IPlayerSkills originalData = get(event.getOriginal());
        IPlayerSkills cloneData = get(event.getEntity());
        cloneData.deserializeNBT(originalData.serializeNBT());
        event.getOriginal().invalidateCaps();
    }

@SubscribeEvent
    public static void syncSkills(PlayerLoggedInEvent event) {
        if (event.getEntity().level().isClientSide) {
            return;
        }
        NetworkDispatcher.network_channel.send(PacketDistributor.PLAYER.with(() -> (ServerPlayer) event.getEntity()), new SyncServerDataMessage());
    }

@SubscribeEvent(priority = EventPriority.LOWEST)
    public static void restoreSkillsAttributeModifiers(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof ServerPlayer player)) {
            return;
        }
        get(player).getPlayerSkills().forEach(skill -> skill.learn(player, false));
    }

@SubscribeEvent
    public static void sendTreeResetMessage(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        if (event.getEntity().level().isClientSide) {
            return;
        }
        IPlayerSkills capability = get(player);
        if (capability.isTreeReset()) {
            player.sendSystemMessage(Component.translatable("skilltree.message.reset").withStyle(ChatFormatting.YELLOW));
            capability.setTreeReset(false);
        }
    }

@SubscribeEvent
    public static void syncPlayerSkills(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof ServerPlayer player)) {
            return;
        }
        NetworkDispatcher.network_channel.send(PacketDistributor.PLAYER.with(() -> player), new SyncPlayerSkillsMessage(player));
    }

public static @NotNull IPlayerSkills get(Player player) {
        return player.getCapability(CAPABILITY).orElseThrow(NullPointerException::new);
    }

public static boolean hasSkills(@NotNull Player player) {
        return player.getCapability(CAPABILITY).isPresent();
    }

@Override
    public <T> @NotNull LazyOptional<T> getCapability(@NotNull Capability<T> cap, @Nullable Direction side) {
        return cap == CAPABILITY ? optionalCapability.cast() : LazyOptional.empty();
    }

@Override
    public CompoundTag serializeNBT() {
        return optionalCapability.orElseThrow(NullPointerException::new).serializeNBT();
    }

@Override
    public void deserializeNBT(CompoundTag compoundTag) {
        optionalCapability.orElseThrow(NullPointerException::new).deserializeNBT(compoundTag);
    }

@SubscribeEvent
    public static void addPoisonedWeaponTooltip(ItemTooltipEvent event) {
        ItemStack itemStack = event.getItemStack();
        if (!PoisonedWeaponEvents.hasPoison(itemStack)) {
            return;
        }
        event.getToolTip().add(Component.empty());
        MutableComponent poisonedWeaponTooltip;
        if (PoisonedWeaponEvents.hasInfinitePoisonUses(itemStack)) {
            poisonedWeaponTooltip = Component.translatable("skilltree.poisoned_weapon");
        } else {
            int usesLeft = PoisonedWeaponEvents.getPoisonUses(itemStack);
            poisonedWeaponTooltip = Component.translatable("skilltree.poisoned_weapon.uses_left", usesLeft);
        }
        event.getToolTip().add(poisonedWeaponTooltip.withStyle(ChatFormatting.LIGHT_PURPLE));
        List<MobEffectInstance> effects = PoisonedWeaponEvents.getPoisonedWeaponEffects(itemStack);
        effects.forEach(mobEffectInstance -> addEffectTooltip(event.getToolTip(), mobEffectInstance));
    }

private static void addEffectTooltip(List<Component> tooltip, MobEffectInstance mobEffectInstance) {
        Style style = TooltipHelper.getSkillBonusStyle(true);
        Component effectNameTooltip = TooltipHelper.getEffectTooltip(mobEffectInstance);
        MutableComponent effectTooltip;
        if (!mobEffectInstance.getEffect().isInstantenous()) {
            int duration = mobEffectInstance.getDuration();
            Component durationTooltip = getDurationTooltip(duration);
            effectTooltip = Component.translatable("skilltree.poisoned_weapon.effect", effectNameTooltip, durationTooltip);
        } else {
            effectTooltip = Component.translatable("skilltree.poisoned_weapon.effect_instant", effectNameTooltip);
        }
        tooltip.add(effectTooltip.withStyle(style));
    }

private static @NotNull Component getDurationTooltip(int duration) {
        int durationSeconds = duration / 20;
        int displayedMinutes = durationSeconds / 60;
        int displayedSeconds = durationSeconds % 60;
        return Component.literal("%s:%02d".formatted(displayedMinutes, displayedSeconds));
    }

public static void drawCenteredOutlinedText(GuiGraphics graphics, String text, int x, int y, int color) {
        Font font = Minecraft.getInstance().font;
        x -= font.width(text) / 2;
        graphics.drawString(font, text, x + 1, y, 0, false);
        graphics.drawString(font, text, x - 1, y, 0, false);
        graphics.drawString(font, text, x, y + 1, 0, false);
        graphics.drawString(font, text, x, y - 1, 0, false);
        graphics.drawString(font, text, x, y, color, false);
    }

public static void drawRectangle(GuiGraphics graphics, int x, int y, int width, int height, int color) {
        graphics.fill(x, y, x + width, y + 1, color);
        graphics.fill(x, y + height - 1, x + width, y + height, color);
        graphics.fill(x, y + 1, x + 1, y + height - 1, color);
        graphics.fill(x + width - 1, y + 1, x + width, y + height - 1, color);
    }

public static float getAngleBetweenButtons(Button button1, Button button2) {
        float x1 = button1.getX() + button1.getWidth() / 2F;
        float y1 = button1.getY() + button1.getHeight() / 2F;
        float x2 = button2.getX() + button2.getWidth() / 2F;
        float y2 = button2.getY() + button2.getHeight() / 2F;
        return (float) Mth.atan2(y2 - y1, x2 - x1);
    }

public static float getDistanceBetweenButtons(Button button1, Button button2) {
        float x1 = button1.getX() + button1.getWidth() / 2F;
        float y1 = button1.getY() + button1.getHeight() / 2F;
        float x2 = button2.getX() + button2.getWidth() / 2F;
        float y2 = button2.getY() + button2.getHeight() / 2F;
        return Mth.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
    }

public static void renderSkillTooltip(PassiveSkillTree skillTree, SkillButton button, GuiGraphics graphics, float x, float y, int width, int height) {
        Font font = Minecraft.getInstance().font;
        int maxWidth = width - 10;
        List<MutableComponent> tooltip = new ArrayList<>();
        for (MutableComponent component : button.getSkillTooltip(skillTree)) {
            if (font.width(component) > maxWidth) {
                tooltip.addAll(TooltipHelper.split(component, font, maxWidth));
            } else {
                tooltip.add(component);
            }
        }
        if (tooltip.isEmpty()) {
            return;
        }
        int tooltipWidth = 0;
        int tooltipHeight = tooltip.size() == 1 ? 8 : 10;
        for (MutableComponent component : tooltip) {
            int k = font.width(component);
            if (k > tooltipWidth) {
                tooltipWidth = k;
            }
            tooltipHeight += font.lineHeight + 2;
        }
        tooltipWidth += 42;
        float tooltipX = x + 12;
        float tooltipY = y - 12;
        if (tooltipX + tooltipWidth > width) {
            tooltipX -= 28 + tooltipWidth;
        }
        if (tooltipY + tooltipHeight + 6 > height) {
            tooltipY = height - tooltipHeight - 6;
        }
        if (tooltipX < 5) {
            tooltipX = 5;
        }
        if (tooltipY < 5) {
            tooltipY = 5;
        }
        graphics.pose().pushPose();
        graphics.pose().translate(tooltipX, tooltipY, 10);
        graphics.fill(1, 4, tooltipWidth - 1, tooltipHeight + 4, 0xDD000000);
        int textX = 5;
        int textY = 2;
        ResourceLocation texture = button.skill.getTooltipFrameTexture();
        graphics.blit(texture, -4, -4, 0, 0, 21, 20, 110, 20);
        graphics.blit(texture, tooltipWidth + 4 - 21, -4, -21, 0, 21, 20, 110, 20);
        int centerWidth = tooltipWidth + 8 - 42;
        int centerX = -4 + 21;
        while (centerWidth > 0) {
            int partWidth = Math.min(centerWidth, 68);
            graphics.blit(texture, centerX, -4, 21, 0, partWidth, 20, 110, 20);
            centerX += partWidth;
            centerWidth -= partWidth;
        }
        MutableComponent title = tooltip.remove(0);
        graphics.drawCenteredString(font, title, tooltipWidth / 2, textY, 0xFFFFFF);
        textY += 19;
        for (MutableComponent component : tooltip) {
            graphics.drawString(font, component, textX, textY, 0xFFFFFF);
            textY += font.lineHeight + 2;
        }
        graphics.pose().popPose();
    }

public static void renderGatewayConnection(GuiGraphics graphics, SkillConnection connection, boolean highlighted, float zoom, float animation) {
        ResourceLocation texture = ResourceLocation.parse("skilltree:textures/screen/long_connection.png");
        graphics.pose().pushPose();
        SkillButton button1 = connection.getFirstButton();
        SkillButton button2 = connection.getSecondButton();
        double connectionX = button1.x + button1.getWidth() / 2F;
        double connectionY = button1.y + button1.getHeight() / 2F;
        graphics.pose().translate(connectionX, connectionY, 0);
        float rotation = ScreenHelper.getAngleBetweenButtons(button1, button2);
        graphics.pose().mulPose(Axis.ZP.rotation(rotation));
        int length = (int) (ScreenHelper.getDistanceBetweenButtons(button1, button2) / zoom);
        graphics.pose().scale(zoom, zoom, 1F);
        graphics.blit(texture, 0, -8, length, 6, -animation, highlighted ? 0 : 6, length, 6, 30, 12);
        graphics.blit(texture, 0, 2, length, 6, animation, highlighted ? 0 : 6, length, 6, -30, 12);
        graphics.pose().popPose();
    }

public static void renderOneWayConnection(GuiGraphics graphics, SkillConnection connection, boolean highlighted, float zoom, float animation) {
        ResourceLocation texture = ResourceLocation.parse("skilltree:textures/screen/one_way_connection.png");
