public static void renderConnection(GuiGraphics graphics, SkillConnection connection, float zoom, float animation) {
        ResourceLocation texture = ResourceLocation.parse("skilltree:textures/screen/direct_connection.png");
        graphics.pose().pushPose();
        SkillButton button1 = connection.getFirstButton();
        SkillButton button2 = connection.getSecondButton();
        double connectionX = button1.x + button1.getWidth() / 2F;
        double connectionY = button1.y + button1.getHeight() / 2F;
        graphics.pose().translate(connectionX, connectionY, 0);
        float rotation = ScreenHelper.getAngleBetweenButtons(button1, button2);
        graphics.pose().mulPose(Axis.ZP.rotation(rotation));
        int length = (int) ScreenHelper.getDistanceBetweenButtons(button1, button2);
        boolean highlighted = button1.skillLearned && button2.skillLearned;
        graphics.pose().scale(1F, zoom, 1F);
        graphics.blit(texture, 0, -3, length, 6, 0, highlighted ? 0 : 6, length, 6, 50, 12);
        boolean shouldAnimate = button1.skillLearned && button2.canLearn || button2.skillLearned && button1.canLearn;
        if (!highlighted && shouldAnimate) {
            RenderSystem.setShaderColor(1F, 1F, 1F, (Mth.sin(animation / 3F) + 1) / 2);
            graphics.blit(texture, 0, -3, length, 6, 0, 0, length, 6, 50, 12);
            RenderSystem.setShaderColor(1F, 1F, 1F, 1F);
        }
        graphics.pose().popPose();
    }

public SkillTreeEditorScreen(ResourceLocation skillTreeId) {
        super(Component.empty());
        this.minecraft = Minecraft.getInstance();
        this.skillTree = SkillTreeEditorData.getOrCreateEditorTree(skillTreeId);
        this.skillButtons = new SkillButtons(skillTree, () -> 0f);
        this.editorWidgets = new SkillTreeEditor(skillButtons);
    }

@Override
    public void init() {
        if (!statsUpdated) {
            ClientPacketListener connection = getMinecraft().getConnection();
            Objects.requireNonNull(connection);
            connection.send(new ServerboundClientCommandPacket(ServerboundClientCommandPacket.Action.REQUEST_STATS));
        }
        if (skillTree == null) {
            getMinecraft().setScreen(null);
            return;
        }
        clearWidgets();
        skillButtons.setWidth(width);
        skillButtons.setHeight(height);
        editorWidgets.setWidth(210);
        editorWidgets.setHeight(10);
        editorWidgets.setX(width - editorWidgets.getWidth());
        editorWidgets.init();
        editorWidgets.increaseHeight(5);
        editorWidgets.setRebuildFunc(this::rebuildWidgets);
        skillButtons.setRebuildFunc(this::rebuildWidgets);
        skillButtons.clearWidgets();
        editorWidgets.getSkills().forEach(editorWidgets::addSkillButton);
        skillButtons.updateSkillConnections();
        calculateMaxScroll();
        addRenderableWidget(skillButtons);
        addRenderableWidget(editorWidgets);
    }

@Override
    protected void rebuildWidgets() {
        getMinecraft().tell(super::rebuildWidgets);
    }

private void calculateMaxScroll() {
        skillButtons.setMaxScrollX(Math.min(0, width / 2 - 350));
        skillButtons.setMaxScrollY(Math.min(0, height / 2 - 350));
        skillButtons.getWidgets().forEach(button -> {
            float skillX = button.skill.getPositionX();
            float skillY = button.skill.getPositionY();
            int maxScrollX = (int) Math.max(skillButtons.getMaxScrollX(), Mth.abs(skillX));
            int maxScrollY = (int) Math.max(skillButtons.getMaxScrollY(), Mth.abs(skillY));
            skillButtons.setMaxScrollX(maxScrollX);
            skillButtons.setMaxScrollY(maxScrollY);
        });
    }

@Override
    public void render(@NotNull GuiGraphics graphics, int mouseX, int mouseY, float partialTick) {
        renderBackground(graphics);
        skillButtons.render(graphics, mouseX, mouseY, partialTick);
        renderOverlay(graphics);
        editorWidgets.render(graphics, mouseX, mouseY, partialTick);
        if (mouseX < editorWidgets.getX() || mouseY > editorWidgets.getHeight()) {
            float tooltipX = mouseX + (prevMouseX - mouseX) * partialTick;
            float tooltipY = mouseY + (prevMouseY - mouseY) * partialTick;
            skillButtons.renderTooltip(graphics, tooltipX, tooltipY);
        }
        prevMouseX = mouseX;
        prevMouseY = mouseY;
    }

private void createBlankSkill() {
        ResourceLocation background = ResourceLocation.fromNamespaceAndPath(SkillTreeMod.MOD_ID, "textures/icons/background/lesser.png");
        ResourceLocation icon = ResourceLocation.fromNamespaceAndPath(SkillTreeMod.MOD_ID, "textures/icons/void.png");
        ResourceLocation border = ResourceLocation.fromNamespaceAndPath(SkillTreeMod.MOD_ID, "textures/tooltip/lesser.png");
        ResourceLocation skillId = SkillNodeEditor.createNewSkillId(skillTree.getId());
        PassiveSkill skill = new PassiveSkill(skillId, 16, background, icon, border, false);
        skill.setPosition(0, 0);
        SkillTreeEditorData.saveEditorSkill(skill);
        SkillTreeEditorData.loadEditorSkill(skill.getId());
        editorWidgets.getSkillTree().getSkillIds().add(skill.getId());
        SkillTreeEditorData.saveEditorSkillTree(editorWidgets.getSkillTree());
    }

@Override
    public boolean shouldCloseOnEsc() {
        if (!shouldCloseOnEsc) {
            shouldCloseOnEsc = true;
            return false;
        }
        return super.shouldCloseOnEsc();
    }

@Override
    public void tick() {
        editorWidgets.onWidgetTick();
    }

private void renderOverlay(GuiGraphics graphics) {
        ResourceLocation texture = ResourceLocation.parse("skilltree:textures/screen/skill_tree_overlay.png");
        RenderSystem.enableBlend();
        graphics.blit(texture, 0, 0, 0, 0F, 0F, width, height, width, height);
        RenderSystem.disableBlend();
    }

@Override
    public void renderBackground(GuiGraphics graphics) {
        ResourceLocation texture = ResourceLocation.parse("skilltree:textures/screen/skill_tree_background.png");
        PoseStack poseStack = graphics.pose();
        poseStack.pushPose();
        poseStack.translate(skillButtons.getScrollX() / 3F, skillButtons.getScrollY() / 3F, 0);
        int size = SkillTreeScreen.BACKGROUND_SIZE;
        graphics.blit(texture, (width - size) / 2, (height - size) / 2, 0, 0F, 0F, size, size, size, size);
        poseStack.popPose();
    }

@Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        return editorWidgets.mouseClicked(mouseX, mouseY, button);
    }

@Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        return editorWidgets.mouseReleased(mouseX, mouseY, button);
    }

@Override
    public boolean mouseScrolled(double mouseX, double mouseY, double amount) {
        return editorWidgets.mouseScrolled(mouseX, mouseY, amount) || skillButtons.mouseScrolled(mouseX, mouseY, amount);
    }

@Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        return editorWidgets.mouseDragged(mouseX, mouseY, button, dragX, dragY) | skillButtons.mouseDragged(mouseX, mouseY, button, dragX, dragY);
    }

@Override
    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
        if (editorWidgets.keyPressed(keyCode, scanCode, modifiers)) {
            if (keyCode == GLFW.GLFW_KEY_ESCAPE) {
                shouldCloseOnEsc = false;
            }
            return true;
        }
        if (keyCode == GLFW.GLFW_KEY_ESCAPE) {
            if (shouldCloseOnEsc()) {
                onClose();
                return true;
            }
        }
        if (keyCode == GLFW.GLFW_KEY_N && Screen.hasControlDown()) {
            createBlankSkill();
            rebuildWidgets();
            return true;
        }
        return false;
    }

@Override
    public boolean charTyped(char codePoint, int modifiers) {
        return editorWidgets.charTyped(codePoint, modifiers);
    }

@Override
    public void onStatsUpdated() {
        statsUpdated = true;
        init();
    }

public SkillTreeScreen(ResourceLocation skillTreeId) {
        super(Component.empty());
        this.skillTree = SkillTreesReloader.getSkillTreeById(skillTreeId);
        this.minecraft = Minecraft.getInstance();
        this.skillButtons = new SkillButtons(skillTree, () -> renderAnimation);
        this.skillTreeWidgets = new SkillTreeWidgets(getLocalPlayer(), skillButtons, skillTree);
        this.skillButtons.setRebuildFunc(this::rebuildWidgets);
        this.skillTreeWidgets.setRebuildFunc(this::rebuildWidgets);
    }

@Override
    public void init() {
        if (!statsUpdated) {
            ClientPacketListener connection = getMinecraft().getConnection();
            Objects.requireNonNull(connection);
            connection.send(new ServerboundClientCommandPacket(ServerboundClientCommandPacket.Action.REQUEST_STATS));
        }
        clearWidgets();
        skillTreeWidgets.clearWidgets();
        skillTreeWidgets.setWidth(width);
        skillTreeWidgets.setHeight(height);
        skillButtons.setWidth(width);
        skillButtons.setHeight(height);
        skillButtons.clearWidgets();
        addSkillButtons();
        skillTreeWidgets.init();
        calculateMaxScroll();
        addRenderableWidget(skillTreeWidgets);
        addRenderableWidget(skillButtons);
    }

private void addSkillButtons() {
        Stream<PassiveSkill> passiveSkills = skillTree.getSkillIds().stream().map(SkillsReloader::getSkillById).filter(Objects::nonNull);
        passiveSkills.forEach(skill -> skillTreeWidgets.addSkillButton(skill, () -> renderAnimation));
        skillButtons.updateSkillConnections();
    }

@Override
    protected void rebuildWidgets() {
        getMinecraft().tell(super::rebuildWidgets);
    }

private void calculateMaxScroll() {
        skillButtons.setMaxScrollX(Math.min(0, width / 2 - 350));
        skillButtons.setMaxScrollY(Math.min(0, height / 2 - 350));
        skillButtons.getWidgets().forEach(button -> {
            float skillX = button.skill.getPositionX();
            float skillY = button.skill.getPositionY();
            int maxScrollX = (int) Math.max(skillButtons.getMaxScrollX(), Mth.abs(skillX));
            int maxScrollY = (int) Math.max(skillButtons.getMaxScrollY(), Mth.abs(skillY));
            skillButtons.setMaxScrollX(maxScrollX);
            skillButtons.setMaxScrollY(maxScrollY);
        });
    }

@Override
    public void render(@NotNull GuiGraphics graphics, int mouseX, int mouseY, float partialTick) {
        renderAnimation += partialTick;
        renderBackground(graphics);
        skillButtons.render(graphics, mouseX, mouseY, partialTick);
        renderOverlay(graphics);
        skillTreeWidgets.render(graphics, mouseX, mouseY, partialTick);
        float tooltipX = mouseX + (prevMouseX - mouseX) * partialTick;
        float tooltipY = mouseY + (prevMouseY - mouseY) * partialTick;
        skillButtons.renderTooltip(graphics, tooltipX, tooltipY);
        prevMouseX = mouseX;
        prevMouseY = mouseY;
    }

