            return;
        }
        SkillBonus<?> defaultBonus = PSTSkillBonuses.ATTRIBUTE.get().createDefaultInstance();
        editor.addSelectionMenu(110, -29, 90, defaultBonus).setResponder(skillBonus -> addSkillBonus(editor, skillBonus))
                .setMessage(Component.literal("Add"));
        PassiveSkill selectedSkill = editor.getFirstSelectedSkill();
        if (selectedSkill == null) {
            return;
        }
        List<SkillBonus<?>> bonuses = selectedSkill.getBonuses();
        for (int i = 0; i < bonuses.size(); i++) {
            final int bonusIndex = i;
            SkillBonus<?> bonus = bonuses.get(i);
            String message = bonus.getSimpleTooltip().getString();
            message = TooltipHelper.getTrimmedString(message, 190);
            editor.addButton(0, 0, 200, 14, message).setPressFunc(button -> {
                SkillBonusEditor skillBonusEditor = new SkillBonusEditor(editor, this, skillBonus -> skillBonusChanged(skillBonus, bonusIndex), () -> getSelectedSkillBonus(bonusIndex));
                editor.selectMenu(skillBonusEditor);
            });
            editor.increaseHeight(19);
        }
    }

private @Nullable SkillBonus<?> getSelectedSkillBonus(int selectedBonusIndex) {
        if (editor.selectedMismatchedBonuses()) {
            return null;
        }
        PassiveSkill selectedSkill = editor.getFirstSelectedSkill();
        if (selectedSkill == null) {
            return null;
        }
        List<SkillBonus<?>> bonuses = selectedSkill.getBonuses();
        if (selectedBonusIndex >= bonuses.size()) {
            editor.selectMenu(previousMenu);
            return null;
        }
        return selectedSkill.getBonuses().get(selectedBonusIndex);
    }

private void skillBonusChanged(@Nullable SkillBonus<?> skillBonus, int selectedBonusIndex) {
        if (skillBonus == null) {
            deleteSelectedSkillBonuses(selectedBonusIndex);
        } else {
            setSkillBonuses(skillBonus, selectedBonusIndex);
        }
    }

private void setSkillBonuses(SkillBonus<?> bonus, int selectedBonusIndex) {
        editor.getSelectedSkills().forEach(s -> s.getBonuses().set(selectedBonusIndex, bonus.copy()));
        editor.saveSelectedSkills();
    }

private void deleteSelectedSkillBonuses(int selectedBonusIndex) {
        editor.getSelectedSkills().forEach(skill -> {
            if (skill.getBonuses().size() > selectedBonusIndex) {
                skill.getBonuses().remove(selectedBonusIndex);
            }
        });
        editor.saveSelectedSkills();
        editor.selectMenu(editor.getSelectedMenu().previousMenu);
    }

private void addSkillBonus(SkillTreeEditor editor, SkillBonus<?> skillBonus) {
        editor.getSelectedSkills().forEach(s -> s.getBonuses().add(skillBonus.copy()));
        editor.saveSelectedSkills();
        editor.selectMenu(editor.getSelectedMenu().previousMenu);
    }

public SkillDescriptionEditor(SkillTreeEditor editor, EditorMenu previousMenu) {
        super(editor, previousMenu);
    }

@Override
    public void init() {
        editor.addButton(0, 0, 90, 14, "Back").setPressFunc(b -> editor.selectMenu(previousMenu));
        if (editor.getSelectedSkills().isEmpty()) {
            return;
        }
        PassiveSkill selectedSkill = editor.getFirstSelectedSkill();
        if (selectedSkill == null) {
            return;
        }
        if (!canEditDescription()) {
            return;
        }
        List<MutableComponent> description = selectedSkill.getDescription();
        editor.addConfirmationButton(110, 0, 90, 14, "Regenerate", "Confirm").setPressFunc(b -> regenerateSkillsDescription());
        editor.increaseHeight(29);
        if (description != null) {
            for (int i = 0; i < description.size(); i++) {
                int selectedLine = i;
                String message = description.get(i).getString();
                Font font = Minecraft.getInstance().font;
                message = TooltipHelper.getTrimmedString(font, message, 190);
                editor.addButton(0, 0, 200, 14, message)
                        .setPressFunc(b -> editor.selectMenu(new SkillDescriptionLineEditor(editor, this, selectedLine)));
                editor.increaseHeight(19);
            }
        }
        editor.increaseHeight(10);
        editor.addButton(0, 0, 90, 14, "Add").setPressFunc(b -> addSelectedSkillsDescriptionLine());
        editor.addConfirmationButton(110, 0, 90, 14, "Clear", "Confirm").setPressFunc(b -> removeSelectedSkillsDescription());
        editor.increaseHeight(19);
    }

private boolean canEditDescription() {
        PassiveSkill selectedSkill = editor.getFirstSelectedSkill();
        if (selectedSkill == null) {
            return false;
        }
        if (editor.getSelectedSkills().size() < 2) {
            return true;
        }
        for (PassiveSkill otherSkill : editor.getSelectedSkills()) {
            List<MutableComponent> description = selectedSkill.getDescription();
            List<MutableComponent> otherDescription = otherSkill.getDescription();
            if (description == null && otherDescription == null) {
                continue;
            }
            if (description == null || otherDescription == null) {
                return false;
            }
            if (description.size() != otherDescription.size()) {
                return false;
            }
            for (int i = 0; i < description.size(); i++) {
                if (!description.get(i).equals(otherDescription.get(i))) {
                    return false;
                }
            }
        }
        return true;
    }

private void regenerateSkillsDescription() {
        editor.getSelectedSkills().forEach(skill -> skill.setDescription(null));
        editor.saveSelectedSkills();
        editor.getSelectedSkills().forEach(skill -> {
            List<MutableComponent> description = new ArrayList<>();
            editor.getSkillButton(skill.getId()).addSkillBonusTooltip(description);
            skill.setDescription(description);
        });
        editor.rebuildWidgets();
    }

private void addSelectedSkillsDescriptionLine() {
        editor.getSelectedSkills().forEach(skill -> {
            List<MutableComponent> description = skill.getDescription();
            if (description == null) {
                description = new ArrayList<>();
                skill.setDescription(description);
            }
            description.add(Component.empty().withStyle(TooltipHelper.getSkillBonusStyle(true)));
        });
        editor.saveSelectedSkills();
        editor.rebuildWidgets();
    }

private void removeSelectedSkillsDescription() {
        editor.getSelectedSkills().forEach(skill -> skill.setDescription(null));
        editor.saveSelectedSkills();
        editor.rebuildWidgets();
    }

