@SubscribeEvent
    public static void saveStuckArrows(LivingHurtEvent event) {
        DamageSource damageSource = event.getSource();
        if (!(damageSource.getDirectEntity() instanceof AbstractArrow arrow)) {
            return;
        }
        if (arrow.pickup != AbstractArrow.Pickup.ALLOWED) {
            return;
        }
        if (!(arrow.getOwner() instanceof Player player)) {
            return;
        }
        AbstractArrowAccessor arrowAccessor = (AbstractArrowAccessor) arrow;
        ItemStack arrowStack = arrowAccessor.invokeGetPickupItem();
        if (arrowStack == null) {
            return;
        }
        List<ArrowRetrievalBonus> skillBonuses = SkillBonusProvider.getSkillBonuses(player, ArrowRetrievalBonus.class);
        if (skillBonuses.isEmpty()) {
            return;
        }
        float retrievalChance = 0f;
        for (ArrowRetrievalBonus bonus : skillBonuses) {
            retrievalChance += bonus.getChance();
        }
        if (player.getRandom().nextFloat() >= retrievalChance) {
            return;
        }
        LivingEntity target = event.getEntity();
        CompoundTag targetPersistentData = target.getPersistentData();
        ListTag stuckArrowsTag = targetPersistentData.getList(STUCK_ARROWS_TAG_NAME, Tag.TAG_COMPOUND);
        stuckArrowsTag.add(arrowStack.save(new CompoundTag()));
        targetPersistentData.put(STUCK_ARROWS_TAG_NAME, stuckArrowsTag);
    }

@SubscribeEvent
    public static void retrieveArrows(LivingDeathEvent event) {
        LivingEntity entity = event.getEntity();
        CompoundTag entityPersistentData = entity.getPersistentData();
        ListTag arrowsTag = entityPersistentData.getList(STUCK_ARROWS_TAG_NAME, Tag.TAG_COMPOUND);
        if (arrowsTag.isEmpty()) {
            return;
        }
        for (Tag tag : arrowsTag) {
            ItemStack arrowStack = ItemStack.of((CompoundTag) tag);
            entity.spawnAtLocation(arrowStack);
        }
    }

@SubscribeEvent
    public static void modifyBlockBreakSpeed(PlayerEvent.BreakSpeed event) {
        Player player = event.getEntity();
        List<BlockBreakSpeedBonus> skillBonuses = SkillBonusProvider.getSkillBonuses(player, BlockBreakSpeedBonus.class);
        if (skillBonuses.isEmpty()) {
            return;
        }
        float multiplier = 1f;
        for (BlockBreakSpeedBonus bonus : skillBonuses) {
            multiplier += bonus.getMultiplier(player);
        }
        event.setNewSpeed(event.getNewSpeed() * multiplier);
    }

@SubscribeEvent(priority = EventPriority.HIGH)
    public static void applyDirectHitCritChance(CriticalHitEvent event) {
        Player player = event.getEntity();
        if (player.level().isClientSide) {
            return;
        }
        if (!(event.getTarget() instanceof LivingEntity hurtEntity)) {
            return;
        }
        DamageSource damageSource = player.level().damageSources().playerAttack(player);
        boolean isVanillaCrit = event.isVanillaCritical();
        float critChance = getCritChance(player, damageSource, hurtEntity);
        boolean isModCrit = player.getRandom().nextFloat() < critChance;
        if (!isVanillaCrit && !isModCrit) {
            return;
        }
        if (!isVanillaCrit) {
            event.setResult(Event.Result.ALLOW);
        }
    }

public static float getCritChance(Player player, DamageSource source, LivingEntity target) {
        float critChance = 0f;
        for (CritChanceBonus bonus : SkillBonusProvider.getSkillBonuses(player, CritChanceBonus.class)) {
            critChance += bonus.getChanceBonus(source, player, target);
        }
        return critChance;
    }

@SubscribeEvent(priority = EventPriority.LOW)
    public static void applyCritBonuses(CriticalHitEvent event) {
        Player player = event.getEntity();
        if (player.level().isClientSide) {
            return;
        }
        if (!(event.getTarget() instanceof LivingEntity hurtEntity)) {
            return;
        }
        boolean isCrit = event.isVanillaCritical() || event.getResult() == Event.Result.ALLOW;
        if (!isCrit) {
            return;
        }
        DamageSource damageSource = player.level().damageSources().playerAttack(player);
        float modCritMultiplier = getCritDamageModifier(player, damageSource, hurtEntity);
        event.setDamageModifier(1.5f + modCritMultiplier);
    }

@SubscribeEvent(priority = EventPriority.LOW)
    public static void applyIndirectHitCritDamage(LivingHurtEvent event) {
        DamageSource damageSource = event.getSource();
        Entity directDamagingEntity = damageSource.getDirectEntity();
        // direct damage, handled by the method above, ignoring
        if (directDamagingEntity instanceof Player) {
            return;
        }
        Entity damagingEntity = damageSource.getEntity();
        if (!(damagingEntity instanceof ServerPlayer player)) {
            return;
        }
        boolean isVanillaCrit = false;
        if (directDamagingEntity instanceof AbstractArrow arrow) {
            isVanillaCrit = arrow.isCritArrow();
        }
        float critChance = CriticalHitChanceBonusHandler.getCritChance(player, damageSource, event.getEntity());
        boolean isModCrit = player.getRandom().nextFloat() < critChance;
        if (!isVanillaCrit && !isModCrit) {
            return;
        }
        LivingEntity hurtEntity = event.getEntity();
        float modCritMultiplier = getCritDamageModifier(player, damageSource, hurtEntity);
        if (isVanillaCrit) {
            event.setAmount(event.getAmount() * (1f + modCritMultiplier));
        } else {
            float vanillaCritMultiplier = 1.5f;
            event.setAmount(event.getAmount() * (vanillaCritMultiplier + modCritMultiplier));
        }
    }

public static float getCritDamageModifier(Player player, DamageSource source, LivingEntity target) {
        float multiplier = 0f;
        for (CritDamageBonus bonus : SkillBonusProvider.getSkillBonuses(player, CritDamageBonus.class)) {
            multiplier += bonus.getDamageBonus(source, player, target);
        }
        return multiplier;
    }

@SubscribeEvent(priority = EventPriority.LOWEST)
    public static void applyDamageAvoidanceBonuses(LivingAttackEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        List<DamageAvoidanceChanceBonus> skillBonuses = SkillBonusProvider.getSkillBonuses(player, DamageAvoidanceChanceBonus.class);
        if (skillBonuses.isEmpty()) {
            return;
        }
        DamageSource damageSource = event.getSource();
        LivingEntity attacker = getAttacker(damageSource);
        float avoidanceChance = 0f;
        for (DamageAvoidanceChanceBonus skillBonus : skillBonuses) {
            avoidanceChance += skillBonus.getChance(damageSource, player, attacker);
        }
        if (player.getRandom().nextFloat() < avoidanceChance) {
            event.setCanceled(true);
            EventListenerBonusHandler.triggerEvent(player, EvasionEventListener.class, (eventListener, skillBonus) -> {
                eventListener.onEvent(player, attacker, skillBonus);
            });
        }
    }

private static @Nullable LivingEntity getAttacker(DamageSource damageSource) {
        Entity sourceEntity = damageSource.getEntity();
        if (sourceEntity instanceof LivingEntity attacker) {
            return attacker;
        } else if (sourceEntity instanceof Projectile projectile && projectile.getOwner() instanceof LivingEntity attacker) {
            return attacker;
        }
        return null;
    }

@SubscribeEvent(priority = EventPriority.LOWEST)
    public static void dealConvertedDamage(LivingHurtEvent event) {
        if (isProcessingConversion) {
            return;
        }
        DamageSource originalDamageSource = event.getSource();
        if (!(originalDamageSource.getEntity() instanceof Player player)) {
            return;
        }
        List<DamageConversionBonus> skillBonuses = SkillBonusProvider.getSkillBonuses(player, DamageConversionBonus.class);
        if (skillBonuses.isEmpty()) {
            return;
        }
        LivingEntity target = event.getEntity();
        float originalDamageAmount = event.getAmount();
        float totalConvertedPercentage = 0f;
        Map<DamageCondition, Float> convertedDamageMap = new HashMap<>();
        for (DamageConversionBonus skillBonus : skillBonuses) {
            if (!skillBonus.canConvertDamage(originalDamageSource)) {
                continue;
            }
            DamageCondition resultDamageSource = skillBonus.getResultDamageCondition();
            float conversionRate = skillBonus.getConversionRate(originalDamageSource, player, target);
            convertedDamageMap.put(resultDamageSource, convertedDamageMap.getOrDefault(resultDamageSource, 0f) + conversionRate);
            totalConvertedPercentage += conversionRate;
        }
        if (convertedDamageMap.isEmpty()) {
            return;
        }
        try {
            isProcessingConversion = true;
            convertedDamageMap.forEach(((damageCondition, conversionPercentage) -> {
                DamageSource newDamageSource = damageCondition.createDamageSource(player);
                float damagePayload = conversionPercentage * originalDamageAmount;
                SkillBonusHandlerUtils.hurtIgnoringInvulnerabilityTime(target, newDamageSource, damagePayload);
            }));
        } finally {
            isProcessingConversion = false;
        }
        event.setAmount(originalDamageAmount * (1 - totalConvertedPercentage));
    }

@SubscribeEvent
    public static void applyEffectDurationBonuses(MobEffectEvent.Added event) {
        LivingEntity target = event.getEntity();
        if (target.level().isClientSide) {
            return;
        }
        Player playerEffectSource = null;
        if (event.getEffectSource() instanceof Player player) {
            playerEffectSource = player;
        }
        if (event.getEffectSource() instanceof Projectile projectile && projectile.getOwner() instanceof Player player) {
            playerEffectSource = player;
        }
        float durationMultiplier = 1f;
        MobEffectInstance effectInstance = event.getEffectInstance();
        MobEffect mobEffect = effectInstance.getEffect();
        // outgoing effects, inflicted by players
        if (playerEffectSource != null) {
            List<EffectDurationBonus> skillBonuses = SkillBonusProvider.getSkillBonuses(playerEffectSource, EffectDurationBonus.class);
            for (EffectDurationBonus skillBonus : skillBonuses) {
                if (skillBonus.getTarget() == SkillBonus.Target.ENEMY) {
                    durationMultiplier += skillBonus.getDurationModifier(mobEffect, playerEffectSource, target);
                }
            }
        }
        // incoming effects, inflicted onto players
        if (target instanceof Player playerTarget) {
            List<EffectDurationBonus> skillBonuses = SkillBonusProvider.getSkillBonuses(playerTarget, EffectDurationBonus.class);
            for (EffectDurationBonus skillBonus : skillBonuses) {
                if (skillBonus.getTarget() == SkillBonus.Target.PLAYER) {
                    durationMultiplier += skillBonus.getDurationModifier(mobEffect, playerEffectSource, target);
                }
            }
        }
        if (durationMultiplier == 1f) {
            return;
        }
        int newDuration = (int) (effectInstance.getDuration() * durationMultiplier);
        newDuration = Math.max(1, newDuration);
        ((MobEffectInstanceAccessor) effectInstance).setDuration(newDuration);
    }

