            return;
        }
        float stealthMultiplier = 0f;
        for (StealthBonus skillBonus : skillBonuses) {
            stealthMultiplier += skillBonus.getStealthMultiplier(player, lookingEntity);
        }
        event.modifyVisibility(1f - stealthMultiplier);
    }

@SubscribeEvent
    public static void tickSkillBonuses(TickEvent.PlayerTickEvent event) {
        if (event.player.isDeadOrDying()) {
            return;
        }
        if (!(event.player instanceof ServerPlayer player)) {
            return;
        }
        if (event.phase == TickEvent.Phase.END) {
            return;
        }
        List<TickingSkillBonus> skillBonuses = SkillBonusProvider.getSkillBonuses(player, TickingSkillBonus.class);
        if (skillBonuses.isEmpty()) {
            return;
        }
        for (TickingSkillBonus bonus : skillBonuses) {
            bonus.tick(player);
        }
    }

