public float getRefundChance(Player player, ItemStack itemStack) {
        if (!playerCondition.test(player)) {
            return 0f;
        }
        if (!itemStackPredicate.test(itemStack)) {
            return 0f;
        }
        return chance * playerMultiplier.getValue(player);
    }

