    public void tick(Player player) {
        if (player.level().getGameTime() % 20 == 0 && !player.level().isClientSide) {
            checkPlayerIdle(player);

            if(player instanceof ServerPlayer)
                IPlayerData.sendUpdatePacketTo(player);
        }
