                .then(Commands.literal("all")
                        .executes(context -> {
                            context.getSource().sendSuccess(() -> Component.translatable("command.scalinghealth.recalculate.start"), true);
                            int processed = recalculateAllEntities(context);
                            context.getSource().sendSuccess(() -> Component.translatable("command.scalinghealth.recalculate.finish", processed), true);
                            return 1;
                        })
                ));
    }

private static int recalculateAllEntities(CommandContext<CommandSourceStack> context) {
        AtomicInteger processed = new AtomicInteger(0);
        context.getSource().getLevel().getEntities().getAll().forEach(entity -> {
            if (entity instanceof Mob mob) {
                MobDifficultyHandler.process(mob, SHDifficulty.affected(entity));
                processed.incrementAndGet();
            }
        });
        return processed.get();
    }

private static int summonEntity(CommandSourceStack source, ResourceLocation id, int difficulty, boolean forceBlight, Vec3 pos, CompoundTag tags, boolean randomizeProperties) throws CommandSyntaxException {
        CompoundTag nbt = tags.copy();
        nbt.putString("id", id.toString());
        ServerLevel world = source.getLevel();
        Entity entity = EntityType.loadEntityRecursive(nbt, world, e -> {
            e.moveTo(pos.x, pos.y, pos.z, e.getYRot(), e.getXRot());
            //noinspection ReturnOfNull
            return !world.addWithUUID(e) ? null : e;
        });
        if (entity == null) {
            throw SUMMON_FAILED.create();
        } else {
            if (randomizeProperties && entity instanceof Mob) {
                Mob mob = (Mob) entity;
                mob.finalizeSpawn(world, world.getCurrentDifficultyAt(entity.blockPosition()), MobSpawnType.COMMAND, null, null);

                if (difficulty > 0) {
                    IDifficultyAffected affected = SHDifficulty.affected(entity);
                    boolean blight = forceBlight || MobDifficultyHandler.shouldBecomeBlight(mob, difficulty);
                    affected.forceDifficulty(difficulty);
                    MobDifficultyHandler.setEntityProperties(mob, affected, blight);
                    affected.setProcessed(true);
                }
            }
            source.sendSuccess(() -> Component.translatable("commands.summon.success", entity.getDisplayName()), true);
            return 1;
        }
    }

public ColorList(ForgeConfigSpec.Builder builder, String path, String comment, int... defaults) {
        // Default list of formatted values
        List<String> defaultList = Arrays
                .stream(defaults)
                .mapToObj(Color::format)
                .collect(Collectors.toList());

        recalculate();

        // Load a string list
        this.config = builder
                .comment(comment)
                .defineList(path, defaultList, o -> o instanceof String && Color.validate((String) o));
    }

public void recalculate()  {
        list = Lazy.of(() -> ImmutableList.copyOf(
                config.get()
                        .stream()
                        .map(Color::parseInt)
                        .collect(Collectors.toList())));
    }

public List<Integer> get() {
        return list.get();
    }

