public static Stream<? extends Player> playersInRange(LevelAccessor world, Vec3i center, long radius) {
        if (radius <= 0)
            return world.players().stream();
        return world.players().stream()
                .filter(p -> MCMathUtils.distanceSq(p, center) < (radius * radius));
    }

